raw_response_text:
{
  "goal": "make cartpole sway left and right at fixed frequency of 60Hz",
  "task_params": [
    {
      "key": "target_frequency",
      "value": 60,
      "description": "Desired sway frequency in Hz"
    },
    {
      "key": "dt",
      "value": 0.02,
      "description": "Time step duration in seconds"
    }
  ],
  "derived_signals": [
    {
      "key": "cart_position_change",
      "expression": "cart_position - prev_cart_position",
      "description": "Change in cart position"
    },
    {
      "key": "cart_velocity_estimate",
      "expression": "cart_position_change / dt",
      "description": "Estimated cart velocity"
    },
    {
      "key": "frequency_error",
      "expression": "abs(cart_velocity_estimate - (2 * 3.141592653589793 * target_frequency * cart_position))",
      "description": "Error from target sway frequency"
    }
  ],
  "reward_terms": [
    {
      "key": "high_motion_reward",
      "label": "High Motion",
      "description": "Reward for large cart velocity",
      "weight": 0.9,
      "enabled": true,
      "expression": "abs(cart_velocity)"
    },
    {
      "key": "smooth_control_reward",
      "label": "Smooth Control",
      "description": "Reward for smooth action changes",
      "weight": 0.8,
      "enabled": true,
      "expression": "-abs(action_0 - prev_action_0)"
    },
    {
      "key": "jerky_control_penalty",
      "label": "Jerky Control",
      "description": "Penalty for jerky control",
      "weight": -0.9,
      "enabled": true,
      "expression": "abs(action_0 - prev_action_0)"
    },
    {
      "key": "low_motion_penalty",
      "label": "Low Motion",
      "description": "Penalty for low cart velocity",
      "weight": -0.8,
      "enabled": true,
      "expression": "-abs(cart_velocity)"
    },
    {
      "key": "frequency_accuracy_reward",
      "label": "Frequency Accuracy",
      "description": "Reward for matching sway frequency",
      "weight": 1.0,
      "enabled": true,
      "expression": "1 / (1 + frequency_error)"
    }
  ],
  "success_metric": "frequency_accuracy_reward",
  "rationale": "Rewards encourage smooth, high-motion swaying at target frequency while penalizing jerky or low motion.",
  "warnings": [
    "Frequency approximation may be noisy due to discrete steps."
  ]
}
